#include "viewer.h"
namespace spng {
FilterConfig Viewer::filterConfig()const{
    FilterConfig c;c.scale=check("resize_check")->isChecked()?real("scale_box")->value():1.;c.interpolation=combo("interp_combo")->currentText();c.highpass=check("highpass_check")->isChecked();c.taps=spin("tap_box")->value();c.cutoff=real("cutoff_box")->value();c.zFilter=check("z_check")->isChecked();c.zWeight=real("z_weight")->value();c.zStep=combo("z_step")->currentIndex()+1;c.binary=check("binary_check")->isChecked();c.threshold=real("threshold_box")->value();c.dilation=check("dilate_check")->isChecked()?spin("dilate_box")->value():1;
    auto exact=[this](QString name,double displayed){auto it=scanExact.constFind(name);return it!=scanExact.cend()&&it->first==displayed?it->second:displayed;};
    if(check("resize_check")->isChecked())c.scale=exact("scale",c.scale);c.cutoff=exact("cutoff",c.cutoff);c.zWeight=exact("z_weight",c.zWeight);c.threshold=exact("threshold",c.threshold);c.taps=int(exact("taps",c.taps));if(check("dilate_check")->isChecked())c.dilation=int(exact("dilation",c.dilation));return c;
}
void Viewer::setParameterWidgets(const FilterConfig& c){
    scanExact.clear();auto setReal=[this](const char* widget,QString key,double value){auto w=real(widget);QSignalBlocker b(w);w->setValue(value);scanExact[key]={w->value(),value};};
    setReal("scale_box","scale",c.scale);setReal("cutoff_box","cutoff",c.cutoff);setReal("z_weight","z_weight",c.zWeight);setReal("threshold_box","threshold",c.threshold);
    for(auto t:{std::tuple<const char*,QString,int>{"dilate_box","dilation",c.dilation},{"tap_box","taps",c.taps}}){auto w=spin(std::get<0>(t));QSignalBlocker b(w);w->setValue(std::get<2>(t));scanExact[std::get<1>(t)]={w->value(),std::get<2>(t)};}
    check("resize_check")->setChecked(c.scale!=1);check("highpass_check")->setChecked(c.highpass);check("z_check")->setChecked(c.zFilter);check("binary_check")->setChecked(c.binary);check("dilate_check")->setChecked(c.dilation>1);combo("interp_combo")->setCurrentText(c.interpolation);combo("z_step")->setCurrentIndex(c.zStep-1);
}
void Viewer::invalidateScanParameters(){invalidate({"params"});scanPending=false;scanError=false;scanSettings.reset();scanExact.clear();get<QLineEdit>("scan_source")->clear();get<QLineEdit>("scan_source")->setToolTip("");label("scan_info")->setText("画像を選択してください。");}
void Viewer::chooseScanParameters(){auto file=QFileDialog::getOpenFileName(this,"スキャン設定を選択",{},"JSON (*.json)");if(file.isEmpty())return;scanOverride=file;scanOverrideScope=currentPath.isEmpty()?QString{}:acquisitionDirectory(currentPath);{QSignalBlocker b(check("scan_auto"));check("scan_auto")->setChecked(true);}reloadScanParameters();}
void Viewer::resetScanParameters(){scanOverride.clear();scanOverrideScope.clear();{QSignalBlocker b(check("scan_auto"));check("scan_auto")->setChecked(true);}reloadScanParameters();}
void Viewer::reloadScanParameters(){
    if(!stack||!check("scan_auto")->isChecked())return;auto path=currentPath;int known=imageLayer(path);auto scope=acquisitionDirectory(path);if(!scanOverride.isEmpty()){if(!scanOverrideScope.isEmpty()&&scanOverrideScope!=scope){scanOverride.clear();scanOverrideScope.clear();}else scanOverrideScope=scope;}
    if(known>=0){QSignalBlocker b(spin("scan_layer"));spin("scan_layer")->setValue(known);}spin("scan_layer")->setEnabled(known<0);int layer=known>=0?known:spin("scan_layer")->value();scanPending=true;scanError=false;scanSettings.reset();get<QLineEdit>("scan_source")->clear();get<QLineEdit>("scan_source")->setToolTip("");FilterConfig defaults;defaults.scale=1.4142;setParameterWidgets(defaults);label("scan_info")->setText(QString("Layer%1のスキャン設定を検索中…").arg(layer));updateControls();auto overridePath=scanOverride;
    using Result=QPair<std::optional<ScanSettings>,QString>;
    run("params",[path,layer,overridePath]()->Result{try{auto source=overridePath.isEmpty()?findParameterFile(path):overridePath;if(source.isEmpty())return {};return {readSettings(source,layer),{}};}catch(const std::exception& e){return {{},QString::fromUtf8(e.what())};}},[this,layer](Result result){scanPending=false;scanError=!result.second.isEmpty();if(scanError)label("scan_info")->setText(QString("Layer%1: %2\n別Layerの値は適用していません。手動設定は自動読み込みをOFFにしてください。").arg(layer).arg(result.second));else if(!result.first)label("scan_info")->setText(QString("Layer%1: 設定JSONが見つかりません。ビューア初期値を表示しています。").arg(layer));else{scanSettings=result.first;auto s=*scanSettings;setParameterWidgets(s.config);get<QLineEdit>("scan_source")->setText(QDir::toNativeSeparators(s.source));get<QLineEdit>("scan_source")->setToolTip(s.source);label("scan_info")->setText(QString("Layer%1: 設定を読み込みました。\n二値化閾値 = %2 + (%3) = %4\nFIR tap=15、Z参照間隔=1。画像処理は「全層へ適用」で実行します。").arg(layer).arg(s.thresholdBase,0,'g',6).arg(s.thresholdPlus,0,'g',6).arg(s.config.threshold,0,'g',6));}updateControls();});
}
}
